MERGE INTO COMPANIES dst
USING (
    SELECT
        53 AS COMPANY_ID,
        'Cedar Enterprise Systems' AS COMPANY_NAME,
        'فرص تدريب وتطوير مهني - عرض تجريبي' AS SLOGAN,
        'Enterprise Systems' AS INDUSTRY,
        'إربد' AS CITY,
        'عنوان عرض تجريبي ضمن إربد، محافظة إربد، الأردن' AS ADDRESS,
        'g02.c17@masar.example.invalid' AS CONTACT_EMAIL,
        null AS PHONE_NUMBER,
        null AS WEBSITE_URL,
        null AS LOGO_FILE_ID,
        'ACTIVE' AS COMPANY_STATUS,
        'PENDING' AS VERIFICATION_STATUS,
        to_timestamp('24-OCT-26 05.54.20.820000000 PM','DD-MON-RR HH.MI.SSXFF AM') AS CREATED_AT,
        to_timestamp('06-NOV-26 04.18.47.184000000 PM','DD-MON-RR HH.MI.SSXFF AM') AS UPDATED_AT,
        'إربد' AS GOVERNORATE
    FROM dual
) src
ON (dst.COMPANY_ID = src.COMPANY_ID)
WHEN NOT MATCHED THEN
    INSERT (COMPANY_ID, COMPANY_NAME, SLOGAN, INDUSTRY, CITY, ADDRESS, CONTACT_EMAIL, PHONE_NUMBER, WEBSITE_URL, LOGO_FILE_ID, COMPANY_STATUS, VERIFICATION_STATUS, CREATED_AT, UPDATED_AT, GOVERNORATE)
    VALUES (src.COMPANY_ID, src.COMPANY_NAME, src.SLOGAN, src.INDUSTRY, src.CITY, src.ADDRESS, src.CONTACT_EMAIL, src.PHONE_NUMBER, src.WEBSITE_URL, src.LOGO_FILE_ID, src.COMPANY_STATUS, src.VERIFICATION_STATUS, src.CREATED_AT, src.UPDATED_AT, src.GOVERNORATE);

